def summarize_nonnegative(values):
    count = 0
    total = 0
    for value in values:
        if value >= 0:
            count += 1
            total += value
    return count, total

print(summarize_nonnegative(iter([3, -2, 0, 5])))
print(summarize_nonnegative(iter([])))

def scale(values, factor):
    for value in values:
        yield value * factor

print(list(scale([1, 2, 3], 10)))
print(list(scale([], 10)))

from itertools import islice

def chunks(values, size):
    if type(size) is not int or size <= 0:
        raise ValueError("size must be a positive integer")
    def generate():
        source = iter(values)
        while True:
            batch = tuple(islice(source, size))
            if not batch:
                return
            yield batch
    return generate()

print(list(chunks(range(5), 2)))
try:
    chunks([], 0)
except ValueError:
    print("rejected at call")

from collections import defaultdict

def totals_by_category(rows):
    totals = defaultdict(int)
    for category, amount in rows:
        totals[category] += amount
    return sorted(totals.items())

print(totals_by_category(iter([("B", 5), ("A", 2), ("B", 3)])))

class Batch:
    def __init__(self, tested, rejected):
        if type(tested) is not int or type(rejected) is not int:
            raise ValueError("counts must be integers")
        if not 0 <= rejected <= tested:
            raise ValueError("invalid counts")
        self.tested = tested
        self.rejected = rejected

    def rejection_rate(self):
        return self.rejected / self.tested if self.tested else None

print(Batch(100, 3).rejection_rate())
print(Batch(0, 0).rejection_rate())

from dataclasses import dataclass

@dataclass(frozen=True)
class Amount:
    gross: int
    refund: int

    def retained(self):
        return self.gross - self.refund

print(Amount(1200, 200).retained())
